45	unique_ptr<BoundStatement> Binder::TryExpandTriggers(QueryNode &node, TableCatalogEntry &table,
46	                                                     TriggerEventType event_type) {
47		D_ASSERT(node.type == QueryNodeType::INSERT_QUERY_NODE || node.type == QueryNodeType::UPDATE_QUERY_NODE ||
48		         node.type == QueryNodeType::DELETE_QUERY_NODE);
49		auto &expanded_tables = global_binder_state->trigger_expanded_tables;
50		if (expanded_tables.find(table) != expanded_tables.end()) {
51			if (global_binder_state->trigger_creation_table == &table) {
52				throw NotImplementedException("Recursive trigger chains are not yet supported (trigger cycle detected "
53				                              "through trigger \"%s\" on table \"%s\")",
54				                              global_binder_state->trigger_creation_name, table.name);
55			}
56			return nullptr;
57		}
58		auto txn = table.ParentCatalog().GetCatalogTransaction(context);
59		// FOR EACH ROW triggers are expanded separately via TryExpandRowTriggers; this path only fires statement triggers.
60		auto before_triggers = table.GetTriggersForEvent(txn, TriggerTiming::BEFORE, event_type, TriggerForEach::STATEMENT);
61		auto after_triggers = table.GetTriggersForEvent(txn, TriggerTiming::AFTER, event_type, TriggerForEach::STATEMENT);
62	
63		// UPDATE OF <cols>: drop triggers whose OF list is disjoint from the SET list.
64		// Triggers without an OF list are unrestricted and always fire.
65		if (event_type == TriggerEventType::UPDATE_EVENT && node.type == QueryNodeType::UPDATE_QUERY_NODE) {
66			auto &update_node = node.Cast<UpdateQueryNode>();
67			identifier_set_t updated_columns;
68			if (update_node.set_info) {
69				updated_columns.insert(update_node.set_info->columns.begin(), update_node.set_info->columns.end());
70			}
71			auto trigger_does_not_fire = [&](const_reference<TriggerCatalogEntry> trig) {
72				const auto &of_cols = trig.get().columns;
73				return !of_cols.empty() && std::none_of(of_cols.begin(), of_cols.end(),
74				                                        [&](const Identifier &c) { return updated_columns.count(c) > 0; });
75			};
76			auto drop_non_firing = [&](vector<const_reference<TriggerCatalogEntry>> &triggers) {
77				triggers.erase(std::remove_if(triggers.begin(), triggers.end(), trigger_does_not_fire), triggers.end());
78			};
79			drop_non_firing(before_triggers);
80			drop_non_firing(after_triggers);
81		}
82	
83		if (before_triggers.empty() && after_triggers.empty()) {
84			return nullptr;
85		}
86		if (node.type == QueryNodeType::INSERT_QUERY_NODE) {
87			auto &insert_node = node.Cast<InsertQueryNode>();
88			if (insert_node.on_conflict_info && insert_node.on_conflict_info->action_type != OnConflictAction::NOTHING) {
89				// Only AFTER triggers can carry REFERENCING NEW TABLE — BEFORE rejects it at CREATE time.
90				for (auto &trigger : after_triggers) {
91					if (!trigger.get().referencing_new_table.empty()) {
92						throw NotImplementedException(
93						    "ON CONFLICT DO UPDATE is not yet supported with REFERENCING NEW TABLE AS triggers");
94					}
95				}
96			}
97		}
98		expanded_tables.insert(table);
99		auto bound = ExpandTriggers(node, table, before_triggers, after_triggers);
100	
101		// Only track this table as expanded for the duration of its own subtree in the trigger chain.
102		expanded_tables.erase(table);
103		return make_uniq<BoundStatement>(std::move(bound));
104	}
