106	static constexpr const char *TRIGGER_BASE_CTE_PREFIX = "__duckdb_trigger_base_";
107	static constexpr const char *TRIGGER_BODY_CTE_PREFIX = "__duckdb_trigger_body_";
108	static constexpr const char *TRIGGER_BEFORE_BODY_CTE_PREFIX = "__duckdb_trigger_before_body_";
