110	static unique_ptr<CommonTableExpressionInfo> MakeTransitionTableAliasCTE(const Identifier &base_cte_name,
111	                                                                         const identifier_set_t &exclude_columns) {
112		auto alias_cte = make_uniq<CommonTableExpressionInfo>();
113		auto alias_select = make_uniq<SelectNode>();
114		auto star = make_uniq<StarExpression>();
115		// Hide injected virtual columns from trigger bodies that SELECT * over the transition table.
116		for (auto &name : exclude_columns) {
117			star->ExcludeListMutable().insert(QualifiedColumnName(name));
118		}
119		alias_select->select_list.push_back(std::move(star));
120		auto alias_ref = make_uniq<BaseTableRef>();
121		alias_ref->SetTable(base_cte_name);
122		alias_select->from_table = std::move(alias_ref);
123		alias_cte->query_node = std::move(alias_select);
124		alias_cte->materialized = CTEMaterialize::CTE_MATERIALIZE_DEFAULT;
125		return alias_cte;
126	}
