128	// Reserved names under which the base UPDATE CTE exposes the captured OLD physical columns, one per physical
129	// column in table order. Computed once per expansion and threaded to every consumer (the base UPDATE binding,
130	// the OLD transition alias, and the NEW-alias exclude set), so no layer re-derives the contract independently.
131	// The prefix is extended until it is not a case-insensitive prefix of any real column name, so the reserved
132	// names cannot collide with a user column (which would otherwise make the OLD alias silently read the NEW value).
133	static vector<Identifier> OldCaptureColumnNames(const TableCatalogEntry &table) {
134		string prefix = "__duckdb_old_col_";
135		bool collides = true;
136		while (collides) {
137			collides = false;
138			for (auto &column : table.GetColumns().Logical()) {
139				auto &name = column.Name();
140				if (name.size() >= prefix.size() &&
141				    StringUtil::CIEquals(name.c_str(), prefix.size(), prefix.c_str(), prefix.size())) {
142					prefix += "_";
143					collides = true;
144					break;
145				}
146			}
147		}
148		vector<Identifier> names;
149		idx_t physical_index = 0;
150		for (auto &column : table.GetColumns().Physical()) {
151			(void)column;
152			names.push_back(Identifier(prefix + to_string(physical_index)));
153			physical_index++;
154		}
155		return names;
156	}
