158	// Recursively replace references to generated columns with a copy of their generated expression, so the result
159	// references only physical columns. This makes the recomputation independent of generated-column declaration
160	// order (a generated column may reference another generated column declared later).
161	static void InlineGeneratedColumnRefs(unique_ptr<ParsedExpression> &expr, const TableCatalogEntry &table) {
162		if (expr->GetExpressionType() == ExpressionType::COLUMN_REF) {
163			auto &colref = expr->Cast<ColumnRefExpression>();
164			if (!colref.IsQualified() && table.GetColumns().ColumnExists(colref.GetColumnName())) {
165				auto &column = table.GetColumns().GetColumn(colref.GetColumnName());
166				if (column.Generated()) {
167					expr = column.GeneratedExpression().Copy();
168					InlineGeneratedColumnRefs(expr, table);
169					return;
170				}
171			}
172		}
173		ParsedExpressionIterator::EnumerateChildren(
174		    *expr, [&](unique_ptr<ParsedExpression> &child) { InlineGeneratedColumnRefs(child, table); });
175	}
