177	// OLD transition alias for UPDATE: the base CTE exposes the pre-update physical columns under internal names.
178	// Rename them back to the real column names and (re)compute generated columns over those OLD values. The result
179	// exposes exactly the logical table columns, in table order — no rowid, physical-only, or capture columns.
180	static unique_ptr<CommonTableExpressionInfo> MakeUpdateOldAliasCTE(const TableCatalogEntry &table,
181	                                                                   const Identifier &base_cte_name,
182	                                                                   const vector<Identifier> &old_capture_names) {
183		// Inner select: rename each captured OLD physical column (exposed under its reserved name) to its real name.
184		auto inner = make_uniq<SelectNode>();
185		idx_t physical_index = 0;
186		for (auto &column : table.GetColumns().Physical()) {
187			auto colref = make_uniq<ColumnRefExpression>(old_capture_names[physical_index]);
188			colref->SetAlias(column.Name());
189			inner->select_list.push_back(std::move(colref));
190			physical_index++;
191		}
192		auto inner_from = make_uniq<BaseTableRef>();
193		inner_from->SetTable(base_cte_name);
194		inner->from_table = std::move(inner_from);
195	
196		auto alias_cte = make_uniq<CommonTableExpressionInfo>();
197		alias_cte->materialized = CTEMaterialize::CTE_MATERIALIZE_DEFAULT;
198	
199		if (!table.HasGeneratedColumns()) {
200			// The renamed physical columns already are the full logical row, in table order.
201			alias_cte->query_node = std::move(inner);
202			return alias_cte;
203		}
204	
205		// Wrap the renamed OLD image so generated columns can be recomputed over it, producing every logical column.
206		auto inner_stmt = make_uniq<SelectStatement>();
207		inner_stmt->node = std::move(inner);
208		auto subquery = make_uniq<SubqueryRef>(std::move(inner_stmt));
209	
210		auto outer = make_uniq<SelectNode>();
211		for (auto &column : table.GetColumns().Logical()) {
212			if (column.Generated()) {
213				auto expr = column.GeneratedExpression().Copy();
214				InlineGeneratedColumnRefs(expr, table);
215				expr->SetAlias(column.Name());
216				outer->select_list.push_back(std::move(expr));
217			} else {
218				outer->select_list.push_back(make_uniq<ColumnRefExpression>(column.Name()));
219			}
220		}
221		outer->from_table = std::move(subquery);
222		alias_cte->query_node = std::move(outer);
223		return alias_cte;
224	}
