226	static vector<unique_ptr<ParsedExpression>> &GetDMLReturningList(QueryNode &node) {
227		switch (node.type) {
228		case QueryNodeType::INSERT_QUERY_NODE:
229			return node.Cast<InsertQueryNode>().returning_list;
230		case QueryNodeType::UPDATE_QUERY_NODE:
231			return node.Cast<UpdateQueryNode>().returning_list;
232		case QueryNodeType::DELETE_QUERY_NODE:
233			return node.Cast<DeleteQueryNode>().returning_list;
234		default:
235			throw InternalException("GetDMLReturningList: unexpected node type");
236		}
237	}
