239	static Identifier GetTableAlias(const QueryNode &node, const Identifier &fallback) {
240		switch (node.type) {
241		case QueryNodeType::INSERT_QUERY_NODE: {
242			auto &n = node.Cast<InsertQueryNode>();
243			if (n.table_ref && !n.table_ref->alias.empty()) {
244				return n.table_ref->alias;
245			}
246			return fallback;
247		}
248		case QueryNodeType::UPDATE_QUERY_NODE: {
249			auto &n = node.Cast<UpdateQueryNode>();
250			if (n.table && !n.table->alias.empty()) {
251				return n.table->alias;
252			}
253			return fallback;
254		}
255		case QueryNodeType::DELETE_QUERY_NODE: {
256			auto &n = node.Cast<DeleteQueryNode>();
257			if (n.table && !n.table->alias.empty()) {
258				return n.table->alias;
259			}
260			return fallback;
261		}
262		default:
263			D_ASSERT(false);
264			return fallback;
265		}
266	}
