268	// Raw table_ref alias (empty if none) — an empty alias lets the binding derive
269	// catalog.schema.table from the entry, so qualified RETURNING columns resolve.
270	static Identifier GetReturningAlias(const QueryNode &node) {
271		switch (node.type) {
272		case QueryNodeType::INSERT_QUERY_NODE:
273			return node.Cast<InsertQueryNode>().table_ref ? node.Cast<InsertQueryNode>().table_ref->alias : Identifier();
274		case QueryNodeType::UPDATE_QUERY_NODE:
275			return node.Cast<UpdateQueryNode>().table ? node.Cast<UpdateQueryNode>().table->alias : Identifier();
276		case QueryNodeType::DELETE_QUERY_NODE:
277			return node.Cast<DeleteQueryNode>().table ? node.Cast<DeleteQueryNode>().table->alias : Identifier();
278		default:
279			return Identifier();
280		}
281	}
