283	// Virtual columns exposed to RETURNING — only DELETE, mirroring the no-trigger path.
284	static virtual_column_map_t ReturningVirtualColumns(const QueryNode &node, const TableCatalogEntry &table) {
285		if (node.type == QueryNodeType::DELETE_QUERY_NODE) {
286			return table.GetVirtualColumns();
287		}
288		return virtual_column_map_t();
289	}
