291	// Virtual columns the RETURNING list references, so the base CTE can materialise them (RETURNING *
292	// does not include rowid).  Matched on the trailing identifier — the only table in scope is the
293	// target.  Returns (id, name) pairs, deduplicated.
294	static vector<pair<column_t, Identifier>> ReferencedVirtualColumns(vector<unique_ptr<ParsedExpression>> &returning_list,
295	                                                                   const virtual_column_map_t &virtual_cols,
296	                                                                   const TableCatalogEntry &table) {
297		vector<pair<column_t, Identifier>> result;
298		if (virtual_cols.empty()) {
299			return result;
300		}
301		// A virtual column shadowed by a real column of the same name is not virtual here: RETURNING *
302		// already materialises the real column, and injecting would duplicate the name.
303		identifier_set_t real_names;
304		for (auto &col : table.GetColumns().Logical()) {
305			real_names.insert(col.Name());
306		}
307		unordered_set<column_t> seen;
308		for (auto &expr : returning_list) {
309			ParsedExpressionIterator::VisitExpression<ColumnRefExpression>(*expr, [&](const ColumnRefExpression &cr) {
310				auto &cn = cr.ColumnNames();
311				if (cn.empty()) {
312					return;
313				}
314				for (auto &vc : virtual_cols) {
315					if (real_names.find(vc.second.name) != real_names.end()) {
316						continue;
317					}
318					if (cn.back() == vc.second.name && seen.insert(vc.first).second) {
319						result.emplace_back(vc.first, vc.second.name);
320					}
321				}
322			});
323		}
324		return result;
325	}
