327	static void AddAfterTriggerCTEs(SelectNode &outer, const vector<const_reference<TriggerCatalogEntry>> &after_triggers,
328	                                const Identifier &base_cte_name, const string &uuid_suffix,
329	                                const identifier_set_t &injected_names, const TableCatalogEntry &table,
330	                                const vector<Identifier> &old_capture_names) {
331		// For UPDATE with OLD capture the base CTE also carries the reserved OLD columns; keep them out of the NEW alias.
332		bool update_old_capture = !old_capture_names.empty();
333		identifier_set_t new_alias_exclude = injected_names;
334		new_alias_exclude.insert(old_capture_names.begin(), old_capture_names.end());
335	
336		for (idx_t i = 0; i < after_triggers.size(); i++) {
337			auto &trigger = after_triggers[i].get();
338			Identifier body_cte_name(string(TRIGGER_BODY_CTE_PREFIX) + to_string(i + 1) + "_" + uuid_suffix);
339	
340			auto trig_cte = make_uniq<CommonTableExpressionInfo>();
341			trig_cte->query_node = trigger.trigger_action->Copy();
342			trig_cte->materialized = CTEMaterialize::CTE_MATERIALIZE_DEFAULT;
343			trig_cte->is_trigger_generated = true;
344	
345			// Scoped to this body so sibling triggers can't see the alias.
346			auto &body_map = trig_cte->query_node->cte_map.map;
347			if (!trigger.referencing_new_table.empty() && body_map.find(trigger.referencing_new_table) == body_map.end()) {
348				body_map[trigger.referencing_new_table] = MakeTransitionTableAliasCTE(base_cte_name, new_alias_exclude);
349			}
350			if (!trigger.referencing_old_table.empty() && body_map.find(trigger.referencing_old_table) == body_map.end()) {
351				// UPDATE captures OLD as reserved columns that must be renamed; INSERT/DELETE expose it as-is.
352				body_map[trigger.referencing_old_table] =
353				    update_old_capture ? MakeUpdateOldAliasCTE(table, base_cte_name, old_capture_names)
354				                       : MakeTransitionTableAliasCTE(base_cte_name, injected_names);
355			}
356	
357			outer.cte_map.map[body_cte_name] = std::move(trig_cte);
358		}
359	}
