361	// Build the trigger CTE chain as a SelectNode: BEFORE bodies → base DML → AFTER bodies.
362	// For RETURNING the outer projection is a plain SELECT *, rebound through ReturningBinder later.
363	static unique_ptr<SelectNode> BuildTriggerChain(const QueryNode &node, const TableCatalogEntry &table,
364	                                                const vector<const_reference<TriggerCatalogEntry>> &before_triggers,
365	                                                const vector<const_reference<TriggerCatalogEntry>> &after_triggers,
366	                                                const string &uuid_suffix, const Identifier &base_cte_name,
367	                                                bool has_returning,
368	                                                const vector<pair<column_t, Identifier>> &injected_virtuals,
369	                                                const vector<Identifier> &old_capture_names,
370	                                                optional_ptr<QueryNode> &out_capture_base) {
371		auto outer = make_uniq<SelectNode>();
372		if (has_returning) {
373			outer->select_list.push_back(make_uniq<StarExpression>());
374		} else {
375			outer->select_list.push_back(
376			    make_uniq<FunctionExpression>("count_star", vector<unique_ptr<ParsedExpression>>()));
377		}
378		auto from_ref = make_uniq<BaseTableRef>();
379		from_ref->SetTable(base_cte_name);
380		from_ref->alias = GetTableAlias(node, table.name);
381		outer->from_table = std::move(from_ref);
382	
383		// BEFORE bodies (no transition tables — REFERENCING is rejected at CREATE time).
384		for (idx_t i = 0; i < before_triggers.size(); i++) {
385			Identifier body_cte_name(string(TRIGGER_BEFORE_BODY_CTE_PREFIX) + to_string(i + 1) + "_" + uuid_suffix);
386			auto trig_cte = make_uniq<CommonTableExpressionInfo>();
387			trig_cte->query_node = before_triggers[i].get().trigger_action->Copy();
388			trig_cte->materialized = CTEMaterialize::CTE_MATERIALIZE_DEFAULT;
389			trig_cte->is_trigger_generated = true;
390			outer->cte_map.map[body_cte_name] = std::move(trig_cte);
391		}
392	
393		// Base CTE: the DML with RETURNING * (full rows for transition tables), plus referenced
394		// virtual columns appended so they are materialised for the RETURNING projection.
395		auto base_node = node.Copy();
396		auto &base_returning = GetDMLReturningList(*base_node);
397		base_returning.push_back(make_uniq<StarExpression>());
398		identifier_set_t injected_names;
399		for (auto &vc : injected_virtuals) {
400			base_returning.push_back(make_uniq<ColumnRefExpression>(vc.second));
401			injected_names.insert(vc.second);
402		}
403		auto base_cte = make_uniq<CommonTableExpressionInfo>();
404		base_cte->query_node = std::move(base_node);
405		base_cte->materialized = CTEMaterialize::CTE_MATERIALIZE_ALWAYS;
406		base_cte->is_trigger_generated = true;
407		// Expose the base UPDATE node so ExpandTriggers can flag it for OLD capture in scoped binder state
408		// (instead of a transient field on the parsed AST).
409		if (!old_capture_names.empty()) {
410			out_capture_base = base_cte->query_node.get();
411		}
412		outer->cte_map.map[base_cte_name] = std::move(base_cte);
413	
414		AddAfterTriggerCTEs(*outer, after_triggers, base_cte_name, uuid_suffix, injected_names, table, old_capture_names);
415		return outer;
416	}
