418	BoundStatement Binder::ExpandTriggers(QueryNode &node, TableCatalogEntry &table,
419	                                      const vector<const_reference<TriggerCatalogEntry>> &before_triggers,
420	                                      const vector<const_reference<TriggerCatalogEntry>> &after_triggers) {
421		D_ASSERT(!before_triggers.empty() || !after_triggers.empty());
422		D_ASSERT(node.type == QueryNodeType::INSERT_QUERY_NODE || node.type == QueryNodeType::UPDATE_QUERY_NODE ||
423		         node.type == QueryNodeType::DELETE_QUERY_NODE);
424	
425		// Drain before copying so the base CTE copy's returning_list starts empty.
426		auto user_returning_list = std::move(GetDMLReturningList(node));
427		bool has_returning = !user_returning_list.empty();
428	
429		auto virtual_columns = ReturningVirtualColumns(node, table);
430		auto injected_virtuals = has_returning ? ReferencedVirtualColumns(user_returning_list, virtual_columns, table)
431		                                       : vector<pair<column_t, Identifier>>();
432	
433		auto uuid_suffix = UUID::ToString(UUID::GenerateRandomUUID());
434		Identifier base_cte_name(TRIGGER_BASE_CTE_PREFIX + uuid_suffix);
435	
436		// Capture the pre-update (OLD) image when this is an UPDATE and at least one AFTER trigger references OLD.
437		// The reserved OLD-capture column names are computed once here and threaded to every consumer.
438		vector<Identifier> old_capture_names;
439		if (node.type == QueryNodeType::UPDATE_QUERY_NODE &&
440		    std::any_of(after_triggers.begin(), after_triggers.end(),
441		                [](const_reference<TriggerCatalogEntry> t) { return !t.get().referencing_old_table.empty(); })) {
442			old_capture_names = OldCaptureColumnNames(table);
443		}
444	
445		optional_ptr<QueryNode> capture_base;
446		auto outer = BuildTriggerChain(node, table, before_triggers, after_triggers, uuid_suffix, base_cte_name,
447		                               has_returning, injected_virtuals, old_capture_names, capture_base);
448		// Request OLD capture on the generated base UPDATE in scoped binder state, active only while binding this
449		// chain. BindNode(UpdateQueryNode) reads the request by node identity, so it never touches the parsed AST.
450		// The reserved CTE presentation names are separate, optional state for the statement-trigger CTE consumer.
451		if (capture_base) {
452			global_binder_state->trigger_old_capture.insert(*capture_base);
453			global_binder_state->trigger_old_capture_cte_names[*capture_base] = old_capture_names;
454		}
455		auto chain = Bind(*outer);
456		if (capture_base) {
457			global_binder_state->trigger_old_capture.erase(*capture_base);
458			global_binder_state->trigger_old_capture_cte_names.erase(*capture_base);
459		}
460	
461		if (!has_returning) {
462			auto &properties = GetStatementProperties();
463			properties.output_type = QueryResultOutputType::FORCE_MATERIALIZED;
464			properties.return_type = StatementReturnType::CHANGED_ROWS;
465			return chain;
466		}
467	
468		// SELECT * over the base CTE yields a projection with contiguous bindings (index, 0..n-1), so we
469		// bind the RETURNING list against that index directly as an identity base-table binding.
470		auto child_bindings = chain.plan->GetColumnBindings();
471		D_ASSERT(!child_bindings.empty() && child_bindings.size() == chain.types.size());
472		auto base_index = child_bindings[0].table_index;
473	
474		// Bind RETURNING with ReturningBinder over a base-table binding of the real table — same rules as
475		// the no-trigger path (rejects aggregates/subqueries/windows, resolves qualified columns, virtual
476		// vs real rowid).  bound_columns is the identity over all logical columns (generated included)
477		// because our RETURNING * child materialises every logical column in order.
478		auto returning_binder_owner = Binder::CreateBinder(context);
479		vector<Identifier> col_names;
480		vector<LogicalType> col_types;
481		vector<ColumnIndex> bound_columns;
482		idx_t logical_count = 0;
483		for (auto &col : table.GetColumns().Logical()) {
484			col_names.push_back(col.Name());
485			col_types.push_back(col.Type());
486			bound_columns.emplace_back(logical_count);
487			logical_count++;
488		}
489		returning_binder_owner->bind_context.AddBaseTable(base_index, GetReturningAlias(node), col_names, col_types,
490		                                                  bound_columns, table, std::move(virtual_columns));
491		ReturningBinder returning_binder(*returning_binder_owner, context);
492	
493		vector<unique_ptr<ParsedExpression>> expanded_returning;
494		returning_binder_owner->ExpandStarExpressions(user_returning_list, expanded_returning);
495		if (expanded_returning.empty()) {
496			throw BinderException("RETURNING list is empty!");
497		}
498		BoundStatement result;
499		vector<unique_ptr<Expression>> proj_exprs;
500		for (auto &returning_expr : expanded_returning) {
501			VerifyNotExcluded(*returning_expr);
502			LogicalType result_type;
503			auto bound_expr = returning_binder.Bind(returning_expr, &result_type);
504			result.names.push_back(bound_expr->GetName());
505			result.types.push_back(result_type);
506			proj_exprs.push_back(std::move(bound_expr));
507		}
508	
509		// Virtual columns bind to a sentinel id, but the chain materialised them as trailing columns at
510		// logical_count + k.  Remap those bindings to their real positions.
511		if (!injected_virtuals.empty()) {
512			unordered_map<column_t, idx_t> remap;
513			for (idx_t k = 0; k < injected_virtuals.size(); k++) {
514				remap[injected_virtuals[k].first] = logical_count + k;
515			}
516			for (auto &expr : proj_exprs) {
517				ExpressionIterator::VisitExpressionMutable<BoundColumnRefExpression>(
518				    expr, [&](BoundColumnRefExpression &colref, unique_ptr<Expression> &) {
519					    auto &binding = colref.BindingMutable();
520					    if (binding.table_index != base_index) {
521						    return;
522					    }
523					    auto it = remap.find(binding.column_index.GetIndexUnsafe());
524					    if (it != remap.end()) {
525						    binding.column_index = ProjectionIndex(it->second);
526					    }
527				    });
528			}
529		}
530	
531		auto returning_projection = make_uniq<LogicalProjection>(GenerateTableIndex(), std::move(proj_exprs));
532		returning_projection->AddChild(std::move(chain.plan));
533		result.plan = std::move(returning_projection);
534	
535		auto &properties = GetStatementProperties();
536		properties.output_type = QueryResultOutputType::FORCE_MATERIALIZED;
537		properties.return_type = StatementReturnType::QUERY_RESULT;
538		return result;
539	}
540	
541	static bool BoundBodyTargetsTable(const LogicalOperator &op, const TableCatalogEntry &table) {
542		if (op.type == LogicalOperatorType::LOGICAL_INSERT) {
543			return &op.Cast<LogicalInsert>().table == &table;
544		}
545		if (op.type == LogicalOperatorType::LOGICAL_DELETE) {
546			return &op.Cast<LogicalDelete>().table == &table;
547		}
548		if (op.type == LogicalOperatorType::LOGICAL_UPDATE) {
549			return &op.Cast<LogicalUpdate>().table == &table;
550		}
551		for (auto &child : op.children) {
552			if (child && BoundBodyTargetsTable(*child, table)) {
553				return true;
554			}
555		}
556		return false;
557	}
558	
559	// Detects a nested LogicalTrigger in a bound trigger body, which means the body targets a table that itself has a
560	// FOR EACH ROW trigger (a cascade). Cascades are rejected for now for two reasons:
561	//  1. Over-firing: the inner trigger's affected-row set gets cross-joined with the outer rows during decorrelation,
562	//     so it fires once per (outer row x inner row) instead of once per inner row.
563	//  2. all firings run as one set-based batch against a single snapshot, so a downstream trigger cannot
564	//     see rows an upstream trigger wrote earlier in the same statement. Correct semantics need per-row execution.
565	bool BoundBodyContainsTrigger(const LogicalOperator &op) {
566		if (op.type == LogicalOperatorType::LOGICAL_TRIGGER) {
567			return true;
568		}
569		for (auto &child : op.children) {
570			if (child && BoundBodyContainsTrigger(*child)) {
571				return true;
572			}
573		}
574		return false;
575	}
576	
577	unique_ptr<BoundStatement> Binder::TryExpandRowTriggers(QueryNode &node,
578	                                                        vector<unique_ptr<ParsedExpression>> &returning_list,
579	                                                        TableCatalogEntry &table, TriggerEventType event_type) {
580		auto &expanded_tables = global_binder_state->trigger_expanded_tables;
581		if (expanded_tables.find(table) != expanded_tables.end()) {
582			return nullptr;
583		}
584		auto triggers = table.GetTriggersForEvent(table.ParentCatalog().GetCatalogTransaction(context),
585		                                          TriggerTiming::AFTER, event_type, TriggerForEach::ROW);
586		if (triggers.empty()) {
587			return nullptr;
588		}
589		if (node.type == QueryNodeType::INSERT_QUERY_NODE && node.Cast<InsertQueryNode>().on_conflict_info) {
590			// Updated rows via ON CONFLICT currently appear in the INSERT affected-row set. This would fire INSERT triggers
591			// for those rows. Therefore, the combination is currently rejected.
592			throw NotImplementedException("ON CONFLICT is not yet supported on tables with FOR EACH ROW triggers");
593		}
594		if (!returning_list.empty()) {
595			throw NotImplementedException("RETURNING is not yet supported on tables with FOR EACH ROW triggers");
596		}
597		expanded_tables.insert(table);
598		auto bound = ExpandRowTriggers(node, returning_list, table, triggers, event_type);
599		expanded_tables.erase(table);
600		return make_uniq<BoundStatement>(std::move(bound));
601	}
602	
603	string Binder::RowScopeName(TriggerEventType event_type) {
604		switch (event_type) {
605		case TriggerEventType::DELETE_EVENT:
606			return "old";
607		default:
608			return "new";
609		}
610	}
611	
612	unique_ptr<ExpressionBinder> Binder::SetupRowScope(TableIndex table_index, const vector<Identifier> &col_names,
613	                                                   const vector<LogicalType> &col_types, const string &scope_name) {
614		bind_context.AddGenericBinding(table_index, Identifier(scope_name), col_names, col_types);
615		auto scope_binder = make_uniq<ExpressionBinder>(*this, context);
616		GetActiveBinders().push_back(*scope_binder);
617		return scope_binder;
618	}
619	
620	BoundStatement Binder::ExpandRowTriggers(QueryNode &node, vector<unique_ptr<ParsedExpression>> &returning_list,
621	                                         const TableCatalogEntry &table,
622	                                         const vector<const_reference<TriggerCatalogEntry>> &triggers,
623	                                         TriggerEventType event_type) {
624		D_ASSERT(!triggers.empty());
625		D_ASSERT(returning_list.empty());
626		returning_list.push_back(make_uniq<StarExpression>());
627	
628		auto uuid_suffix = UUID::ToString(UUID::GenerateRandomUUID());
629		Identifier base_cte_name(TRIGGER_BASE_CTE_PREFIX + uuid_suffix);
630	
631		auto base_cte = make_uniq<CommonTableExpressionInfo>();
632		base_cte->query_node = node.Copy();
633		base_cte->materialized = CTEMaterialize::CTE_MATERIALIZE_ALWAYS;
634		base_cte->is_trigger_generated = true;
635	
636		auto outer = make_uniq<SelectNode>();
637		outer->select_list.push_back(make_uniq<FunctionExpression>("count_star", vector<unique_ptr<ParsedExpression>>()));
638		auto from_ref = make_uniq<BaseTableRef>();
639		from_ref->SetTable(base_cte_name);
640		outer->from_table = std::move(from_ref);
641		outer->cte_map.map[base_cte_name] = std::move(base_cte);
642	
643		auto bound = Bind(*outer);
644		auto &base_mat_cte = bound.plan->Cast<LogicalMaterializedCTE>();
645		auto cte_table_idx = base_mat_cte.table_index;
646	
647		// proj_idx is the binding source for NEW.col (INSERT) / OLD.col (DELETE) refs in trigger bodies.
648		vector<Identifier> col_names;
649		vector<LogicalType> col_types;
650		for (auto &col : table.GetColumns().Physical()) {
651			col_names.push_back(col.GetName());
652			col_types.push_back(col.GetType());
653		}
654	
655		auto cte_ref_idx = GenerateTableIndex();
656		auto cte_ref = make_uniq<LogicalCTERef>(cte_ref_idx, cte_table_idx, col_types, col_names, false);
657		cte_ref->ResolveOperatorTypes();
658	
659		auto proj_idx = GenerateTableIndex(); // the table_index for NEW/OLD bindings
660		vector<unique_ptr<Expression>> proj_exprs;
661		for (idx_t i = 0; i < col_types.size(); i++) {
662			proj_exprs.push_back(make_uniq<BoundColumnRefExpression>(col_names[i], col_types[i],
663			                                                         ColumnBinding(cte_ref_idx, ProjectionIndex(i))));
664		}
665		auto new_rows_proj = make_uniq<LogicalProjection>(proj_idx, std::move(proj_exprs));
666		new_rows_proj->children.push_back(std::move(cte_ref));
667		new_rows_proj->ResolveOperatorTypes();
668	
669		auto row_scope_name = RowScopeName(event_type);
670		auto new_scope_binder = SetupRowScope(proj_idx, col_names, col_types, row_scope_name);
671	
672		unique_ptr<LogicalOperator> trigger_plan = std::move(new_rows_proj);
673		for (idx_t i = 0; i < triggers.size(); i++) {
674			auto &trigger = triggers[i].get();
675	
676			auto child_binder = Binder::CreateBinder(context, this);
677			auto body_copy = trigger.trigger_action->Copy();
678			auto bound_body = child_binder->Bind(*body_copy);
679	
680			CorrelatedColumns corr_cols = std::move(child_binder->correlated_columns);
681			if (corr_cols.empty()) {
682				throw BinderException("FOR EACH ROW trigger \"%s\" on table \"%s\" must reference at least one NEW or OLD "
683				                      "column in the trigger body (use FOR EACH STATEMENT if row data is not needed)",
684				                      trigger.name, table.name);
685			}
686	
687			if (BoundBodyTargetsTable(*bound_body.plan, table)) {
688				throw BinderException("FOR EACH ROW trigger \"%s\" on table \"%s\" writes to the trigger table "
689				                      "(self-referential triggers are not supported)",
690				                      trigger.name, table.name);
691			}
692	
693			if (BoundBodyContainsTrigger(*bound_body.plan)) {
694				throw NotImplementedException("FOR EACH ROW trigger \"%s\" on table \"%s\" writes to a table that has its "
695				                              "own FOR EACH ROW trigger (cascading row triggers are not yet supported)",
696				                              trigger.name, table.name);
697			}
698	
699			auto logi_trig = make_uniq<LogicalTrigger>(trigger.name.GetIdentifierName(), trigger.timing, trigger.event_type,
700			                                           std::move(corr_cols));
701			logi_trig->children.push_back(std::move(trigger_plan));
702			logi_trig->children.push_back(std::move(bound_body.plan));
703			logi_trig->ResolveOperatorTypes();
704			trigger_plan = std::move(logi_trig);
705		}
706		// remove row_scope_binder
707		GetActiveBinders().pop_back();
708	
709		Identifier trigger_cte_name(string(TRIGGER_BODY_CTE_PREFIX) + "row_" + uuid_suffix);
710		auto trigger_cte_idx = GenerateTableIndex();
711		auto outer_query = std::move(bound.plan->children[1]);
712	
713		auto trigger_mat_cte =
714		    make_uniq<LogicalMaterializedCTE>(trigger_cte_name, trigger_cte_idx, col_types.size(), std::move(trigger_plan),
715		                                      std::move(outer_query), CTEMaterialize::CTE_MATERIALIZE_DEFAULT);
716		trigger_mat_cte->ResolveOperatorTypes();
717	
718		bound.plan->children[1] = std::move(trigger_mat_cte);
719		bound.plan->ResolveOperatorTypes();
720	
721		auto &properties = GetStatementProperties();
722		properties.return_type = StatementReturnType::CHANGED_ROWS;
723		properties.output_type = QueryResultOutputType::FORCE_MATERIALIZED;
724		return bound;
725	}
726	
727	} // namespace duckdb
